object Threat_Retreat_Decision_supervisor_tr_SystemTestAPI {
  /** helper method to set the values of all incoming ports
    * @param api_arrival_fact incoming data port
    * @param api_defense_facts incoming data port
    * @param api_phase_context incoming data port
    * @param api_threat_fact incoming data port
    */
  def put_concrete_inputs(api_arrival_fact: Mining_Threat_Retreat_Supervisor.Arrival_Fact,
                          api_defense_facts: Mining_Threat_Retreat_Supervisor.Defense_Facts,
                          api_phase_context: Mining_Threat_Retreat_Supervisor.Phase_Context,
                          api_threat_fact: Mining_Threat_Retreat_Supervisor.Qualified_Threat): Unit = {
    put_arrival_fact(api_arrival_fact)
    put_defense_facts(api_defense_facts)
    put_phase_context(api_phase_context)
    put_threat_fact(api_threat_fact)
  }

  // setter for incoming data port
  def put_arrival_fact(value: Mining_Threat_Retreat_Supervisor.Arrival_Fact): Unit = {
    Art.insertInInfrastructurePort(Arch.Mining_Threat_Retreat_Supervisor_Root_Instance_supervisor_tr.operational_api.arrival_fact_Id, Mining_Threat_Retreat_Supervisor.Arrival_Fact_Payload(value))
  }

  // setter for incoming data port
  def put_defense_facts(value: Mining_Threat_Retreat_Supervisor.Defense_Facts): Unit = {
    Art.insertInInfrastructurePort(Arch.Mining_Threat_Retreat_Supervisor_Root_Instance_supervisor_tr.operational_api.defense_facts_Id, Mining_Threat_Retreat_Supervisor.Defense_Facts_Payload(value))
  }

  // setter for incoming data port
  def put_phase_context(value: Mining_Threat_Retreat_Supervisor.Phase_Context): Unit = {
    Art.insertInInfrastructurePort(Arch.Mining_Threat_Retreat_Supervisor_Root_Instance_supervisor_tr.operational_api.phase_context_Id, Mining_Threat_Retreat_Supervisor.Phase_Context_Payload(value))
  }

  // setter for incoming data port
  def put_threat_fact(value: Mining_Threat_Retreat_Supervisor.Qualified_Threat): Unit = {
    Art.insertInInfrastructurePort(Arch.Mining_Threat_Retreat_Supervisor_Root_Instance_supervisor_tr.operational_api.threat_fact_Id, Mining_Threat_Retreat_Supervisor.Qualified_Threat_Payload(value))
  }

  def fetchContainer(): scp_candidate.Mining_Threat_Retreat_Supervisor.Threat_Retreat_Decision_supervisor_tr_PostState_Container_PS = {
    if (runtimeMonitorStream.contains(Arch.Mining_Threat_Retreat_Supervisor_Root_Instance_supervisor_tr.id)) {
      val (_, postContainer_) = runtimeMonitorStream.get(Arch.Mining_Threat_Retreat_Supervisor_Root_Instance_supervisor_tr.id).get
      return postContainer_.asInstanceOf[scp_candidate.Mining_Threat_Retreat_Supervisor.Threat_Retreat_Decision_supervisor_tr_PostState_Container_PS]
    }
    else {
      assert(F, s"No post state recorded for ${Arch.Mining_Threat_Retreat_Supervisor_Root_Instance_supervisor_tr.name}")
      halt(s"No post state recorded for ${Arch.Mining_Threat_Retreat_Supervisor_Root_Instance_supervisor_tr.name}")
    }
  }

  def check_concrete_outputs(api_response_proposal: Mining_Threat_Retreat_Supervisor.Response_Proposal): Unit = {
    var failureReasons: ISZ[ST] = ISZ()

    val actual_response_proposal = get_api_response_proposal()
    if (api_response_proposal != actual_response_proposal) {
      failureReasons = failureReasons :+ st"'response_proposal' did not match expected.  Expected: $api_response_proposal, Actual: $actual_response_proposal"
    }

    assert(failureReasons.isEmpty, st"${(failureReasons, "\n")}".render)
  }

  def get_api_response_proposal(): Mining_Threat_Retreat_Supervisor.Response_Proposal = {
    return fetchContainer().api_response_proposal
  }
}